// Embedded base64 bytes for the preset topic cards added after
// whiteboard_library_data.dart was generated — kept in a separate file so
// that large, mostly-static generated file never needs touching again.
// Same purpose as that file's own bytes: instant rendering in the Library
// sheet (lib/widgets/whiteboard_library_sheet.dart's _PresetImageTile)
// without an asset-bundle round trip, and — more importantly — a reliable
// non-empty payload for voice_room_detail_screen.dart's
// _addLibraryItemToWhiteboard to upload even if rootBundle.load() for the
// real asset file ever fails for some reason; see WhiteboardLibraryItem
// .bytes, which merges this with whiteboard_library_data.dart's own set.
import 'dart:convert';
import 'dart:typed_data';

class WhiteboardLibraryDataExtra {
  static const String topic_inspirationBase64 =
      '';
  static const String topic_humanityBase64 =
      '';
  static const String topic_biggest_flawBase64 =
      '';
  static const String topic_defining_traitBase64 =
      '';
  static const String topic_people_changeBase64 =
      '';
  static const String topic_been_in_loveBase64 =
      '';

  static Uint8List getBytes(String key) {
    final b64 = switch (key) {
      'topic_inspiration' => topic_inspirationBase64,
      'topic_humanity' => topic_humanityBase64,
      'topic_biggest_flaw' => topic_biggest_flawBase64,
      'topic_defining_trait' => topic_defining_traitBase64,
      'topic_people_change' => topic_people_changeBase64,
      'topic_been_in_love' => topic_been_in_loveBase64,
      _ => '',
    };
    if (b64.isEmpty) return Uint8List(0);
    return base64Decode(b64);
  }
}
